using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelTrainer>();

var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");

// Train the model on startup if it doesn't exist yet
if (!File.Exists(modelPath))
{
    var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
    using var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
    var trainer = new TicketModelTrainer(loggerFactory.CreateLogger<TicketModelTrainer>());
    trainer.TrainAndSave(dataPath, modelPath);
}

// Extract label names from the trained model's metadata
var mlContext = new MLContext();
var loadedModel = mlContext.Model.Load(modelPath, out _);
var predictionEngine = mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(loadedModel);
var labelColumn = predictionEngine.OutputSchema["Score"];
var slotNames = new VBuffer<ReadOnlyMemory<char>>();
labelColumn.GetSlotNames(ref slotNames);
var labels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
builder.Services.AddSingleton(new LabelRegistry(labels));

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

